### 第 3 题（电子学会四级模拟·结构体）执行以下代码，输出结果是？（ ）

```cpp
struct Point { int x, y; };
void f(Point *p) { p->x = 10; }
Point p = {1, 2};
f(&p);
cout << p.x;
```

- A. 1
- B. 2
- C. 10
- D. 随机值

questions.explanation:
利用异或性质：a ⊕ a = 0、a ⊕ 0 = a、且异或满足交换律结合律。所有成对的数异或后抵消为 0，剩下的就是出现奇数次的数。参考程序：

```cpp
#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;
    int ans = 0;
    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        ans ^= x;
    }
    cout << ans << endl;
    return 0;
}
```

从最高位开始逐位做除法：维护当前余数 r，每读入一位数字后 r = r × 10 + 该位，商的当前位为 r / b，更新余数 r %= b，最后去掉商的前导零。参考程序：

```cpp
#include <iostream>
#include <string>
using namespace std;

int main() {
    string a;
    long long b;
    cin >> a >> b;
    string q = "";
    long long r = 0;
    for (int i = 0; i < a.size(); i++) {
        r = r * 10 + (a[i] - '0');
        int d = r / b;
        if (!(q.empty() && d == 0)) q += char('0' + d);
        r %= b;
    }
    if (q.empty()) q = "0";
    cout << q << endl;
    cout << r << endl;
    return 0;
}
```

高精度乘法：从最低位开始逐位乘 k，当前位 = (原位×k+进位) % 10，进位 = (原位×k+进位)/10，最后处理进位。

参考程序：

```cpp
#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

string mul(string a, int k)
{
    string r = "";
    int carry = 0;
    for (int i = a.size() - 1; i >= 0; i--)
    {
        int s = (a[i] - '0') * k + carry;
        r += char(s % 10 + '0');
        carry = s / 10;
    }
    while (carry) { r += char(carry % 10 + '0'); carry /= 10; }
    reverse(r.begin(), r.end());
    return r;
}

int main()
{
    string p;
    int k;
    cin >> p >> k;
    cout << mul(p, k) << endl;
    return 0;
}
```

高精度乘加：每次计算当前阶乘 term = term × i（高精度乘一位），再累加到 sum（高精度加），循环 i=1..n。

参考程序：

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

vector<int> add(vector<int> a, vector<int> b)
{
    vector<int> r;
    int carry = 0, i = 0;
    while (i < a.size() || i < b.size() || carry)
    {
        int s = carry;
        if (i < a.size()) s += a[i];
        if (i < b.size()) s += b[i];
        r.push_back(s % 10);
        carry = s / 10;
        i++;
    }
    return r;
}

vector<int> mul(vector<int> a, int k)
{
    vector<int> r;
    int carry = 0;
    for (int i = 0; i < a.size(); i++)
    {
        int s = a[i] * k + carry;
        r.push_back(s % 10);
        carry = s / 10;
    }
    while (carry) { r.push_back(carry % 10); carry /= 10; }
    return r;
}

int main()
{
    int n;
    cin >> n;
    vector<int> sum(1, 0), term(1, 1);
    for (int i = 1; i <= n; i++)
    {
        term = mul(term, i);
        sum = add(sum, term);
    }
    for (int i = sum.size() - 1; i >= 0; i--) cout << sum[i];
    cout << endl;
    return 0;
}
```
